def expand(beta,selected):
    coeff={}
    def add(t,c):
        coeff[t]=coeff.get(t,0)+float(c)
    def product(s,t,c):
        if s is None:
            add(t,c);return
        if t is None:
            add(s,c);return
        j=s[0];k=t[0]
        if len(s)==1 and len(t)==1:
            add((j,k,0),c);return
        h=s[1] if len(s)==2 else (-4.2 if j==0 else 0)
        g=t[1] if len(t)==2 else 0
        add((j,k,h,g),c)
        if len(s)==1 and j==0: add(t,-4.2*c)
    add(None,beta[0])
    for ii,(j,a) in enumerate(desc):
        for r,s in enumerate(rawterms[j]):
            add(s,beta[1+ii]*transforms[j][r,a])
    for ii,(jj,kk) in enumerate(selected):
        j,a=desc[jj];k,b=desc[kk]
        c=beta[1+len(desc)+ii]
        for r,s in enumerate(rawterms[j]):
            for u,t in enumerate(rawterms[k]):
                product(s,t,c*transforms[j][r,a]*transforms[k][u,b])
    return {t:c for t,c in coeff.items() if abs(c)>1e-9}
