    pred=np.full(len(X),coeff.get(None,0))
    for t,c in coeff.items():
        if t is None:continue
        if len(t)==1:
            pred+=c*X[:,t[0]]
        elif len(t)==2:
            pred+=c*np.maximum(X[:,t[0]]-t[1],0)
        elif len(t)==3:
            pred+=c*X[:,t[0]]*X[:,t[1]]
        else:
            pred+=c*np.maximum(X[:,t[0]]-t[2],0)*np.maximum(X[:,t[1]]-t[3],0)
    return pred
